<body>
  <a class="skip-link" href="#main-content">Skip to main content</a>
  <div id="app"></div>
  <script>
    const root = document.getElementById("app");

    const formState = {
      values: {
        fullName: "",
        email: "",
        phone: ""
      },
      errors: {
        fullName: "",
        email: "",
        phone: ""
      },
      status: {
        message: "",
        state: "idle"
      }
    };

    const fieldConfig = {
      fullName: {
        label: "Full name",
        required: true,
        autocomplete: "name",
        type: "text",
        placeholder: "Jordan Lee"
      },
      email: {
        label: "Email address",
        required: true,
        autocomplete: "email",
        type: "email",
        placeholder: "jordan@example.com"
      },
      phone: {
        label: "Phone number",
        required: false,
        autocomplete: "tel",
        type: "tel",
        placeholder: "+1 555 123 4567",
        helperText: "Optional. Use digits with spaces or punctuation, for example +1 555 123 4567."
      }
    };

    function validateFullName(value) {
      if (!value.trim()) {
        return "Enter your full name.";
      }
      if (value.trim().length < 2) {
        return "Full name must be at least 2 characters.";
      }
      return "";
    }

    function validateEmail(value) {
      if (!value.trim()) {
        return "Enter your email address.";
      }
      const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
      if (!emailPattern.test(value.trim())) {
        return "Enter a valid email address.";
      }
      return "";
    }

    function validatePhone(value) {
      if (!value.trim()) {
        return "";
      }
      const phonePattern = /^\+?[0-9\s().-]{7,20}$/;
      if (!phonePattern.test(value.trim())) {
        return "Enter a valid phone number using digits and common separators.";
      }
      return "";
    }

    function validateField(name, value) {
      if (name === "fullName") return validateFullName(value);
      if (name === "email") return validateEmail(value);
      if (name === "phone") return validatePhone(value);
      return "";
    }

    function FormField(name) {
      const config = fieldConfig[name];
      const value = formState.values[name];
      const error = formState.errors[name];
      const helperId = config.helperText ? name + "-helper" : "";
      const errorId = name + "-error";
      const describedBy = [helperId, error ? errorId : ""].filter(Boolean).join(" ");

      return `
        <div class="form-field">
          <label for="${name}">
            ${config.label}${config.required ? ' <span class="required-indicator" aria-hidden="true">*</span>' : ""}
          </label>
          <input
            id="${name}"
            name="${name}"
            type="${config.type}"
            autocomplete="${config.autocomplete}"
            placeholder="${config.placeholder}"
            value="${escapeHtml(value)}"
            ${config.required ? "required" : ""}
            aria-required="${config.required ? "true" : "false"}"
            aria-invalid="${error ? "true" : "false"}"
            ${describedBy ? `aria-describedby="${describedBy}"` : ""}
          />
          ${config.helperText ? `<p class="helper-text" id="${helperId}">${config.helperText}</p>` : ""}
          <p class="error-text" id="${errorId}" aria-live="polite">${error}</p>
        </div>
      `;
    }

    function SupportForm() {
      const statusState = formState.status.state;
      return `
        <section class="card" aria-labelledby="support-form-title">
          <form id="support-form" novalidate>
            <h2 id="support-form-title">Contact support</h2>
            ${FormField("fullName")}
            ${FormField("email")}
            ${FormField("phone")}
            <p class="status-text" data-state="${statusState}" aria-live="polite">${formState.status.message}</p>
            <button type="submit">Send request</button>
          </form>
        </section>
      `;
    }

    function SupportPage() {
      return `
        <div class="page-shell">
          <main id="main-content">
            <section class="hero" aria-labelledby="page-title">
              <p class="eyebrow">Support</p>
              <h1 id="page-title">We’re here to help.</h1>
              <p>Send a quick message and our support team will follow up with the right next steps as soon as possible.</p>
            </section>
            ${SupportForm()}
          </main>
        </div>
      `;
    }

    function App() {
      return SupportPage();
    }

    function escapeHtml(value) {
      return value
        .replaceAll("&", "&amp;")
        .replaceAll("<", "&lt;")
        .replaceAll(">", "&gt;")
        .replaceAll('"', "&quot;")
        .replaceAll("'", "&#39;");
    }

    function render() {
      root.innerHTML = App();
    }

    root.addEventListener("input", (event) => {
      if (!(event.target instanceof HTMLInputElement)) {
        return;
      }

      const { name, value } = event.target;
      formState.values[name] = value;
      formState.errors[name] = validateField(name, value);

      if (formState.status.state !== "idle") {
        formState.status = { message: "", state: "idle" };
      }

      render();

      const activeField = document.getElementById(name);
      if (activeField instanceof HTMLInputElement) {
        activeField.focus();
      }
    });

    root.addEventListener("focusout", (event) => {
      if (!(event.target instanceof HTMLInputElement)) {
        return;
      }

      const { name, value } = event.target;
      formState.values[name] = value;
      formState.errors[name] = validateField(name, value);
      render();
    });

    root.addEventListener("submit", (event) => {
      if (!(event.target instanceof HTMLFormElement) || event.target.id !== "support-form") {
        return;
      }

      event.preventDefault();

      const nextErrors = {
        fullName: validateFullName(formState.values.fullName),
        email: validateEmail(formState.values.email),
