   <script>
     const root = document.getElementById("app");

     const formState = {
       values: {
         fullName: "",
         email: "",
         phone: ""
       },
       errors: {
         fullName: "",
         email: "",
         phone: ""
       },
       status: {
         message: "",
         state: "idle"
       }
     };

     const fieldConfig = {
       fullName: {
         label: "Full name",
         required: true,
         autocomplete: "name",
         type: "text",
         placeholder: "Jordan Lee"
       },
       email: {
         label: "Email address",
         required: true,
         autocomplete: "email",
         type: "email",
         placeholder: "jordan@example.com"
       },
       phone: {
         label: "Phone number",
         required: false,
         autocomplete: "tel",
         type: "tel",
         placeholder: "+1 555 123 4567",
         helperText: "Optional. Use digits with spaces or punctuation, for example +1 555 123 4567."
       }
     };

     function validateFullName(value) {
       if (!value.trim()) {
         return "Enter your full name.";
       }
       if (value.trim().length < 2) {
         return "Full name must be at least 2 characters.";
       }
       return "";
     }

     function validateEmail(value) {
       if (!value.trim()) {
         return "Enter your email address.";
       }
       const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
       if (!emailPattern.test(value.trim())) {
         return "Enter a valid email address.";
       }
       return "";
     }

     function validatePhone(value) {
       if (!value.trim()) {
         return "";
       }
       const phonePattern = /^\+?[0-9\s().-]{7,20}$/;
       if (!phonePattern.test(value.trim())) {
         return "Enter a valid phone number using digits and common separators.";
       }
       return "";
     }

     function validateField(name, value) {
       if (name === "fullName") return validateFullName(value);
       if (name === "email") return validateEmail(value);
       if (name === "phone") return validatePhone(value);
       return "";
     }

     function FormField(name) {
       const config = fieldConfig[name];
       const value = formState.values[name];
       const error = formState.errors[name];
       const helperId = config.helperText ? name + "-helper" : "";
       const errorId = name + "-error";
       const describedBy = [helperId, error ? errorId : ""].filter(Boolean).join(" ");

       return `
         <div class="form-field">
           <label for="${name}">
             ${config.label}${config.required ? ' <span class="required-indicator" aria-hidden="true">*</span>' : ""}
           </label>
           <input
             id="${name}"
             name="${name}"
             type="${config.type}"
             autocomplete="${config.autocomplete}"
             placeholder="${config.placeholder}"
